def analyze_mappings(demo, demo_idx):
    inp = demo['input']
    out = demo['output']
    bg = inp[0][0]

    # Build mapping based on same positions
    mapping = {}
    seen_in_out = set()
    seen_out_only = set()

    for r in range(len(inp)):
        for c in range(len(inp[0])):
            inp_val = inp[r][c]
            out_val = out[r][c]

            if out_val != bg and out_val not in seen_in_out:
                seen_in_out.add(out_val)
                if inp_val != bg:
                    if inp_val not in mapping:
                        mapping[inp_val] = out_val
                    elif mapping[inp_val] != out_val:
                        print(f"  Conflict at ({r},{c}): {inp_val} → {out_val} (already {mapping[inp_val]})")
                else:
                    if inp_val in seen_out_only:
                        print(f"  Same position mapping: {inp_val} → {out_val}")
                    elif inp_val not in mapping:
                        mapping[inp_val] = out_val
                    else:
                        print(f"  At ({r},{c}): same position, {inp_val} → {out_val} but {inp_val} → {mapping[inp_val]} before")

    print(f"Dem {demo_idx} basic mapping (same positions): {mapping}")

for i, demo in enumerate(demos):
    analyze_mappings(demo, i)

